import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as projectRepo from "@/server/repositories/project-repository";
import * as pmRepo from "@/server/repositories/project-member-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as commentService from "@/server/services/comment-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("private works", async () => {
  const t = await createTenant("privx", "business");
  const priv = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "Secret", slug: "secret", key: "SEC", description: null, visibility: "private", leadId: null, color: "#6366f1", targetDate: null });
  const issue = await issueService.createIssue(t.actors.admin, issueInput(t.org.id, priv.id));
  const m = t.actors.member;
  await expect(projectService.getProject(m, t.org.id, "secret")).rejects.toBeInstanceOf(NotFoundError);
  await expect(issueService.getIssue(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
  await expect(issueService.getBoard(m, t.org.id, priv.id)).rejects.toBeInstanceOf(NotFoundError);
  await expect(commentService.getThread(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
  const lp = await projectService.listProjects(m, { orgId: t.org.id, limit: 20, cursor: null } as never);
  expect(lp.items.map((p) => p.project.id)).not.toContain(priv.id);
  const la = await projectService.listProjects(t.actors.admin, { orgId: t.org.id, limit: 20, cursor: null } as never);
  expect(la.total).toBe(lp.total + 1);
  const li = await issueService.listIssues(m, { orgId: t.org.id, limit: 20, cursor: null } as never);
  expect(li.items.map((i) => i.id)).not.toContain(issue.id);
  await pmRepo.addProjectMember(t.org.id, priv.id, m.userId);
  expect(await projectService.canViewProject(m, priv)).toBe(true);
  const li2 = await issueService.listIssues(m, { orgId: t.org.id, limit: 20, cursor: null } as never);
  expect(li2.items.map((i) => i.id)).toContain(issue.id);
  expect(await projectService.canViewProject(t.actors.viewer, priv)).toBe(false);
  await projectRepo.updateProject({ orgId: t.org.id, projectId: priv.id, leadId: t.actors.viewer.userId } as never);
  const lv = await projectService.listProjects(t.actors.viewer, { orgId: t.org.id, limit: 20, cursor: null } as never);
  expect(lv.items.map((p) => p.project.id)).toContain(priv.id);
});
EOF
